functions._daConst:
function _daConst() {
  return {
    STORE: "bd_history", PREFIX: "bdaudit_",
    IDENTITY_PATH: "fleet-identity.enc.json", GH_OWNER: "apndrewn", GH_REPO: "eli-data",
  };
}

functions._daEsc:
function _daEsc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

// Decode one stored/CDN audit row → record. Mirrors build_draft._bdAuditDecode
// so the viewer doesn't hard-depend on build_draft being loaded.

functions._daDecode:
function _daDecode(eli, row) {
  if (!row) return Promise.resolve(null);
  function _unpack(env) {
    if (!env || env.payload == null) return null;
    if (!env._bdaZ) { try { return JSON.parse(env.payload); } catch (_e) { return null; } }
    try {
      var bin = atob(env.payload);
      var bytes = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      return JSON.parse(window.pako.inflate(bytes, { to: "string" }));
    } catch (_e) { return null; }
  }
  if (row._bdaPlain) return Promise.resolve(_unpack(row._bdaPlain));
  if (row._bdaEnc && typeof window._eliDecryptFromRepo === "function") {
    var cipher = "";
    try { cipher = (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet("eli_lib_cipher") || "") : ""; } catch (_e) {}
    if (!cipher) return Promise.resolve(null);
    return window._eliDecryptFromRepo(cipher, row._bdaEnc)
      .then(function (env) { return _unpack(env); })
      .catch(function () { return null; });
  }
  return Promise.resolve(null);
}

functions._daDecodeAll:
function _daDecodeAll(eli, rows) {
  return Promise.all((rows || []).map(function (r) { return _daDecode(eli, r); }))
    .then(function (recs) { return recs.filter(Boolean); });
}

// ── Data sources ──────────────────────────────────────────────────────
// OWN: local bd_history rows whose id starts bdaudit_.

functions._daLoadOwn:
function _daLoadOwn(eli) {
  var C = _daConst();
  return eli.storage.getAll(C.STORE).then(function (rows) {
    var mine = (rows || []).filter(function (r) { return r && typeof r.id === "string" && r.id.indexOf(C.PREFIX) === 0; });
    return _daDecodeAll(eli, mine);
  });
}

// FLEET: list audit/*.json from the CDN, fetch each, decode all records.

functions._daListFleetFiles:
function _daListFleetFiles(pat) {
  var C = _daConst();
  var url = "https://api.github.com/repos/" + C.GH_OWNER + "/" + C.GH_REPO + "/contents/audit?t=" + Date.now();
  return fetch(url, { headers: { "Authorization": "Bearer " + pat, "Accept": "application/vnd.github+json" } })
    .then(function (r) { if (!r.ok) return []; return r.json(); })
    .then(function (list) {
      return (Array.isArray(list) ? list : []).filter(function (f) {
        return f && f.name && /\.json$/.test(f.name) && f.download_url;
      });
    }).catch(function () { return []; });
}

functions._daLoadFleet:
function _daLoadFleet(eli, pat) {
  return _daListFleetFiles(pat).then(function (files) {
    return Promise.all(files.map(function (f) {
      return fetch(f.download_url, { cache: "no-store" })
        .then(function (r) { return r.ok ? r.json() : null; })
        .then(function (j) { return (j && Array.isArray(j.records)) ? j.records : []; })
        .catch(function () { return []; });
    })).then(function (perFile) {
      var all = [];
      perFile.forEach(function (recs) { all = all.concat(recs); });
      return _daDecodeAll(eli, all);
    });
  });
}

// ── UUID → name lookup (fleet mode) — reuse admin_fleet's shared cache when
// present, else load fleet-identity.enc.json directly. ──

functions._daLoadIdentityLookup:
function _daLoadIdentityLookup(eli, pat) {
  try {
    if (window._eli3_admin_fleet_lookup) return Promise.resolve(window._eli3_admin_fleet_lookup);
  } catch (_e) {}
  if (!pat) return Promise.resolve(null);
  var C = _daConst();
  var url = "https://api.github.com/repos/" + C.GH_OWNER + "/" + C.GH_REPO +
    "/contents/" + encodeURIComponent(C.IDENTITY_PATH) + "?t=" + Date.now();
  return fetch(url, { headers: { "Authorization": "Bearer " + pat, "Accept": "application/vnd.github+json" } })
    .then(function (r) { if (!r.ok) return null; return r.json(); })
    .then(function (j) {
      if (!j || !j.content) return null;
      var cipher = "";
      try { cipher = (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet("eli_lib_cipher") || "") : ""; } catch (_e) {}
      if (!cipher || typeof window._eliDecryptFromRepo !== "function") return null;
      var blob;
      try { blob = JSON.parse(atob(String(j.content).replace(/\s/g, ""))); } catch (_e) { return null; }
      return window._eliDecryptFromRepo(cipher, blob).then(function (map) {
        try { window._eli3_admin_fleet_lookup = map; } catch (_e2) {}
        return map;
      }).catch(function () { return null; });
    }).catch(function () { return null; });
}

functions._daResolveName:
function _daResolveName(lookup, userId) {
  if (!userId) return "(unknown)";
  if (lookup && lookup[userId]) {
    var e = lookup[userId];
    return e.name || e.displayName || e.email || userId;
  }
  return userId; // fall back to raw UUID
}

functions._daFmtDate:
function _daFmtDate(ts) {
  if (!ts) return "—";
  try {
    var d = new Date(ts);
    return d.toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" });
  } catch (_e) { return String(ts); }
}

// Per-step completion map for a record. New records carry r.stepsDone; older
// ones predate it, so fall back to the linear inference from stepsReached
// (which is what those records implicitly assumed anyway).

functions._daStepsDone:
function _daStepsDone(r) {
  if (r && r.stepsDone && typeof r.stepsDone === "object") return r.stepsDone;
  var s = (r && r.stepsReached) || 0;
  return { logic: s >= 1, fill: s >= 2, errorReview: s >= 3, saved: s >= 4, emailed: false, _inferred: true };
}

// ── Main entry ──────────────────────────────────────────────────────────

functions.showDraftAudit:
function showDraftAudit(eli, opts) {
  opts = opts || {};
  var mode = opts.mode === "fleet" ? "fleet" : "own";
  var host = (eli && eli.ui && typeof eli.ui.claimOutput === "function") ? eli.ui.claimOutput() : document.getElementById("output");
  if (!host) return;
  host.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_da_root";
  host.appendChild(root);

  var title = mode === "fleet" ? "Draft Audit — Fleet" : "My Draft History";
  var icon = mode === "fleet" ? "🛡️" : "📋";
  var sub = mode === "fleet"
    ? "Every Build Draft run across all colleagues. Recipes are decrypted locally; names resolved via the identity lookup. Your own runs show here immediately — others appear after their next sync."
    : "Every draft you've built — the recipe (template + your Step 1 choices + Step 2 fills) so it can be recreated on any machine.";
  root.innerHTML =
    '<div class="_da_topbar">' +
      '<div class="_da_topbar_inner">' +
        '<div class="_da_topbar_text">' +
          '<div class="_da_eyebrow">' + (mode === "fleet" ? "ADMIN · RESTRICTED" : "YOUR ACTIVITY") + '</div>' +
          '<div class="_da_title"><span class="_da_title_icon">' + icon + '</span>' + _daEsc(title) + '</div>' +
          '<div class="_da_sub">' + _daEsc(sub) + '</div>' +
        '</div>' +
        '<button class="_da_btn _da_btn_gold" id="_da_refresh">↻ Refresh</button>' +
      '</div>' +
    '</div>' +
    '<div class="_da_body">' +
      '<div class="_da_summary" id="_da_summary"></div>' +
      '<div class="_da_controls">' +
        '<div class="_da_search"><span class="_da_search_icon">🔍</span>' +
          '<input type="text" id="_da_filter" class="_da_filter" placeholder="Filter by CP ref, type, entity, third party, requester…"></div>' +
        '<label class="_da_chk"><input type="checkbox" id="_da_completedonly"> Completed drafts only (4/4)</label>' +
      '</div>' +
      '<div class="_da_status" id="_da_status"></div>' +
      '<div class="_da_list" id="_da_list"></div>' +
    '</div>';

  var statusEl = root.querySelector("#_da_status");
  var listEl = root.querySelector("#_da_list");
  var summaryEl = root.querySelector("#_da_summary");
  var filterEl = root.querySelector("#_da_filter");
  var completedEl = root.querySelector("#_da_completedonly");
  function _status(m, k) { statusEl.textContent = m || ""; statusEl.className = "_da_status" + (k ? " _da_status_" + k : ""); }

  var _records = [];
  var _lookup = null;

  function _getPat() {
    try { return (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet("eli_user_github_pat") || "") : ""; } catch (_e) { return ""; }
  }

  function _load() {
    _status("Loading…");
    if (mode === "fleet") {
      var pat = _getPat();
      if (!pat) { _status("Admin GitHub token missing — import credentials in Admin Data Hub.", "err"); return; }
      // Fleet = CDN audit/*.json (synced from every user, on their 3h cycle)
      // MERGED with this admin's OWN local bd_history — so a draft you just
      // built shows immediately here instead of waiting for the next push.
      // Dedup by runId; own-only runs get a "local, not yet synced" marker.
      Promise.all([_daLoadFleet(eli, pat), _daLoadIdentityLookup(eli, pat), _daLoadOwn(eli)]).then(function (res) {
        var fleet = res[0] || []; _lookup = res[1] || null; var own = res[2] || [];
        var byRun = {}; var localOnly = 0;
        fleet.forEach(function (r) { if (!r) return; r._synced = true; byRun[r.runId || r.id] = r; });
        own.forEach(function (r) {
          if (!r) return; var k = r.runId || r.id;
          if (!byRun[k]) { r._localOnly = true; localOnly++; byRun[k] = r; }
        });
        _records = Object.keys(byRun).map(function (k) { return byRun[k]; });
        _status(_records.length + " run(s) across the fleet" +
          (localOnly ? " · " + localOnly + " of yours not yet synced to the CDN" : "") + ".", "ok");
        _render();
      }).catch(function (e) { _status("Load failed: " + (e && e.message || "unknown"), "err"); });
    } else {
      _daLoadOwn(eli).then(function (recs) {
        _records = recs || [];
        _status(_records.length + " draft(s) in your history.", "ok");
        _render();
      }).catch(function (e) { _status("Load failed: " + (e && e.message || "unknown"), "err"); });
    }
  }

  function _filtered() {
    var f = String(filterEl.value || "").trim().toLowerCase();
    var only4 = completedEl.checked;
    return _records.filter(function (r) {
      if (only4 && (r.stepsReached || 0) < 4) return false;
      if (!f) return true;
      var hay = [r.cpRef, r.agreementType, r.cpEntity, r.thirdParty, r.requesterName].join(" ").toLowerCase();
      return hay.indexOf(f) !== -1;
    }).sort(function (a, b) { return (b.completedAt || 0) - (a.completedAt || 0); });
  }

  function _render() {
    var rows = _filtered();
    // Summary tiles.
    var byStep = { 0: 0, 1: 0, 2: 0, 3: 0, 4: 0 };
    _records.forEach(function (r) { var s = r.stepsReached || 0; if (byStep[s] != null) byStep[s]++; });
    summaryEl.innerHTML =
      '<div class="_da_tile"><div class="_da_tilen">' + _records.length + '</div><div class="_da_tilel">Total runs</div></div>' +
      '<div class="_da_tile _da_t4"><div class="_da_tilen">' + byStep[4] + '</div><div class="_da_tilel">Completed · 4/4</div></div>' +
      '<div class="_da_tile _da_t3"><div class="_da_tilen">' + byStep[3] + '</div><div class="_da_tilel">Reached step 3</div></div>' +
      '<div class="_da_tile _da_tlow"><div class="_da_tilen">' + (byStep[0] + byStep[1] + byStep[2]) + '</div><div class="_da_tilel">Dropped early</div></div>';
    if (!rows.length) { listEl.innerHTML = '<div class="_da_empty">No matching runs.</div>'; return; }
    listEl.innerHTML = rows.map(_daRenderCard.bind(null, mode, _lookup)).join("");
    Array.prototype.forEach.call(listEl.querySelectorAll("[data-da-toggle]"), function (b) {
      b.onclick = function () {
        var card = b.closest("._da_card");
        var det = card.querySelector("._da_details");
        var open = det.style.display !== "none";
        det.style.display = open ? "none" : "block";
        b.textContent = open ? "▶ Recipe" : "▼ Recipe";
      };
    });
  }

  filterEl.oninput = _render;
  completedEl.onchange = _render;
  root.querySelector("#_da_refresh").onclick = _load;
  _load();
}

// Card markup — shared, top-level so it's window-attached. Shows metadata
// row + a collapsible recipe (Step 1 answers + Step 2 fills as key/value).

functions._daRenderCard:
function _daRenderCard(mode, lookup, r) {
  var step = r.stepsReached || 0;
  var stepBadge = '<span class="_da_step _da_step_' + step + '">' + step + ' / 4</span>';
  var who = (mode === "fleet")
    ? '<span class="_da_who">' + _daEsc(_daResolveName(lookup, r.userId)) + '</span>'
    : '';
  var localChip = (mode === "fleet" && r._localOnly)
    ? '<span class="_da_localchip" title="Built on this machine — not yet pushed to the CDN">⏳ local · not synced</span>'
    : '';
  function _kvRows(obj, withheld) {
    if (withheld) return '<div class="_da_kv_empty">🔒 Step 2 fills weren\'t shared to the CDN — they stay local on the author\'s machine.</div>';
    var keys = Object.keys(obj || {});
    if (!keys.length) return '<div class="_da_kv_empty">No values recorded for this step.</div>';
    return '<div class="_da_kv_grid">' + keys.map(function (k) {
      return '<div class="_da_kv"><span class="_da_kv_k">' + _daEsc(k) + '</span><span class="_da_kv_v">' + _daEsc(obj[k]) + '</span></div>';
    }).join("") + '</div>';
  }
  var sd = _daStepsDone(r);
  var stepDefs = [["logic", "Logic"], ["fill", "Fill"], ["errorReview", "Error Review"], ["saved", "Saved"], ["emailed", "Emailed"]];
  var pills = stepDefs.map(function (d) {
    var on = !!sd[d[0]];
    return '<span class="_da_pill ' + (on ? "_da_pill_on" : "_da_pill_off") + '">' +
      (on ? "✓" : "✗") + " " + _daEsc(d[1]) + '</span>';
  }).join("");
  var stepsRow = '<div class="_da_steps">' + pills +
    (sd._inferred ? '<span class="_da_steps_note">inferred from legacy record</span>' : '') + '</div>';
  return '<div class="_da_card _da_card_s' + step + (r._localOnly ? ' _da_card_local' : '') + '">' +
    '<div class="_da_cardhdr">' +
      stepBadge +
      '<div class="_da_cardtitle">' + _daEsc(r.cpRef || "(no CP ref)") +
        '<span class="_da_cardtype">' + _daEsc(r.agreementType || "Unknown type") + '</span></div>' +
      who + localChip +
      '<span class="_da_carddate">' + _daEsc(_daFmtDate(r.completedAt)) + '</span>' +
    '</div>' +
    stepsRow +
    '<div class="_da_cardmeta">' +
      '<span class="_da_meta"><span class="_da_meta_l">Entity</span><span class="_da_meta_v">' + _daEsc(r.cpEntity || "—") + '</span></span>' +
      '<span class="_da_meta"><span class="_da_meta_l">Third party</span><span class="_da_meta_v">' + _daEsc(r.thirdParty || "—") + '</span></span>' +
      '<span class="_da_meta"><span class="_da_meta_l">Requester</span><span class="_da_meta_v">' + _daEsc(r.requesterName || "—") + '</span></span>' +
      '<span class="_da_meta"><span class="_da_meta_l">Template</span><span class="_da_meta_v">' + _daEsc(r.templateName || r.templateId || "—") + '</span></span>' +
      '<button class="_da_btn _da_btn_sm" data-da-toggle="1">▶ Recipe</button>' +
    '</div>' +
    '<div class="_da_details" style="display:none;">' +
      '<div class="_da_section_h">Step 1 — Logic choices</div>' + _kvRows(r.step1Answers, false) +
      '<div class="_da_section_h">Step 2 — Inserted values' + (r._fillsWithheld ? ' <span class="_da_withheld">🔒 withheld</span>' : '') + '</div>' + _kvRows(r.step2Fills, !!r._fillsWithheld) +
      '<div class="_da_recipe_note">Template <code>' + _daEsc(r.templateName || r.templateId || "?") + '</code>' +
        (r.templateVersion ? ' @ ' + _daEsc(r.templateVersion) : '') + ' + these choices recreate the draft.</div>' +
    '</div>' +
  '</div>';
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.register) return;

  function _open(mode, statKey) {
    try { if (eli.stats && eli.stats.record && statKey) eli.stats.record(statKey); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showDraftAudit !== "function") {
      eli.log.event("tool", "draft_audit_fn_missing", {});
      if (typeof showToast === "function") showToast("Draft Audit failed to load", "err");
      return;
    }
    try { window.showDraftAudit(eli, { mode: mode }); }
    catch (e) {
      eli.log.event("tool", "draft_audit_failed", { mode: mode, msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: {
      app_draft_audit: function () { _open("own", "appOpenedDraftAudit"); },
      app_admin_draft_audit: function () { _open("fleet", "appOpenedAdminDraftAudit"); },
    },
    draft_audit: { open: function () { _open("own"); }, openFleet: function () { _open("fleet"); } },
  });

  eli.log.event("tool", "draft_audit_initialized", {});
}

jsonTools.css:
/* tools/draft_audit/style.css — premium light surface (tool panel).
   Single accent: gold #c9a227. Navy header, slate neutrals, readable
   high-contrast text. Class prefix `_da_`. */

._da_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f1f5f9;
  padding: 0 0 40px 0;
  min-height: 100vh;
  box-sizing: border-box;
  /* Kernel .output-area is a transparent flex column; without grow the tool
     sizes to content and scrolling exposes the dashboard navy. Proven in
     template_searcher / admin_fleet. */
  flex: 1 0 auto;
}
.beta-ui-active .output-area:has(> ._da_root),
.output-area:has(> ._da_root) { background: #f1f5f9 !important; }

/* ─── Top bar (full-bleed navy gradient + gold accent) ─────────────── */
._da_topbar {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
  padding: 22px 28px;
}
._da_topbar_inner {
  max-width: 1080px; margin: 0 auto;
  display: flex; align-items: flex-start; justify-content: space-between; gap: 18px;
}
._da_topbar_text { min-width: 0; }
._da_eyebrow { font: 800 9px/1 Inter, sans-serif; letter-spacing: 1.4px; text-transform: uppercase; color: #d4af37; margin-bottom: 7px; }
._da_title { font: 800 24px/1.15 "Book Antiqua", Georgia, serif; color: #fff; letter-spacing: -0.2px; display: flex; align-items: center; gap: 10px; }
._da_title_icon { font-size: 22px; }
._da_sub { font-size: 12px; line-height: 1.55; color: rgba(255,255,255,0.74); margin-top: 8px; max-width: 760px; }

/* ─── Body wrapper ─────────────────────────────────────────────────── */
