._da_card_local { border-left-style: dashed; }

._da_cardhdr { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-bottom: 1px solid #eef2f7; flex-wrap: wrap; }
._da_step { font: 800 11px/1 Inter, sans-serif; padding: 5px 9px; border-radius: 7px; color: #fff; background: #94a3b8; flex: 0 0 auto; }
._da_step_4 { background: #1e9e57; } ._da_step_3 { background: #e08a1e; }
._da_step_2, ._da_step_1, ._da_step_0 { background: #d24437; }
._da_cardtitle { font: 800 15px/1.2 Inter, sans-serif; color: #0f172a; flex: 1 1 auto; min-width: 0; display: flex; align-items: baseline; gap: 9px; flex-wrap: wrap; }
._da_cardtype { font: 600 11px/1 Inter, sans-serif; color: #475569; background: #eef2f7; padding: 3px 8px; border-radius: 999px; }
._da_carddate { font-size: 11px; font-weight: 600; color: #94a3b8; flex: 0 0 auto; }
._da_who { font: 700 11px/1 Inter, sans-serif; color: #1565c0; background: #e0edfb; border: 1px solid #93c5fd; padding: 3px 9px; border-radius: 999px; }
._da_localchip { font: 700 10px/1 Inter, sans-serif; color: #92400e; background: #fef3c7; border: 1px solid #f59e0b; padding: 3px 8px; border-radius: 999px; }

/* Per-step completion pills */
._da_steps { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; padding: 10px 16px; border-bottom: 1px solid #eef2f7; }
._da_pill { font: 700 11px/1 Inter, sans-serif; padding: 4px 9px; border-radius: 999px; border: 1px solid transparent; white-space: nowrap; }
._da_pill_on { color: #137a43; background: #e9f6ee; border-color: #bfe3cb; }
._da_pill_off { color: #94a3b8; background: #f4f6fa; border-color: #e2e8f1; }
._da_steps_note { font: 500 10px/1 Inter, sans-serif; color: #b08900; background: #fef9e7; border: 1px solid #f4e2a8; padding: 3px 8px; border-radius: 999px; }

._da_cardmeta { display: flex; gap: 22px; flex-wrap: wrap; align-items: center; padding: 11px 16px; background: #fafbfc; }
._da_meta { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
._da_meta_l { font: 700 9px/1 Inter, sans-serif; letter-spacing: .05em; text-transform: uppercase; color: #94a3b8; }
._da_meta_v { font-size: 13px; font-weight: 600; color: #1e293b; }

/* ─── Recipe detail ────────────────────────────────────────────────── */
._da_details { padding: 8px 16px 16px; background: #fbfcfe; border-top: 1px solid #eef2f7; }
._da_section_h { font: 800 10px/1 Inter, sans-serif; letter-spacing: .07em; text-transform: uppercase; color: #475569; margin: 14px 0 8px; }
._da_kv_grid { display: grid; grid-template-columns: 1fr; gap: 1px; background: #eef2f7; border: 1px solid #eef2f7; border-radius: 8px; overflow: hidden; }
._da_kv { display: flex; gap: 12px; padding: 8px 12px; background: #fff; font-size: 13px; }
._da_kv_k { flex: 0 0 38%; max-width: 38%; color: #475569; font-weight: 700; word-break: break-word; }
._da_kv_v { flex: 1 1 auto; color: #0f172a; word-break: break-word; }
._da_kv_empty { font-size: 12.5px; color: #94a3b8; font-style: italic; padding: 8px 2px; }
._da_recipe_note { margin-top: 14px; font-size: 11.5px; color: #64748b; line-height: 1.5; }
._da_recipe_note code { background: #eef2f7; color: #334155; padding: 2px 6px; border-radius: 4px; font-size: 11px; }
._da_withheld { font: 800 9px/1 Inter, sans-serif; color: #92400e; background: #fef3c7; border: 1px solid #f59e0b; padding: 2px 6px; border-radius: 4px; letter-spacing: .04em; }
._da_empty { padding: 40px 24px; text-align: center; color: #94a3b8; font-size: 14px; background: #fff; border: 1px dashed #cbd5e1; border-radius: 10px; }

@media (max-width: 720px) {
  ._da_summary { grid-template-columns: repeat(2, 1fr); }
  ._da_kv_k { flex-basis: 45%; max-width: 45%; }
}
